// Build the INDIA Signal 2000: the ~2,000 largest Indian companies, upserted
// into bito_directory with region='in'. Two sources, merged:
//
//   1. Apollo band sweep — mixed_companies/search filtered to India,
//      walked from the largest employee band down. Real orgs, real domains,
//      no hallucination risk.
//   2. Curated seed (scripts/india-seed.json, generated by sector agents) —
//      guarantees the obvious giants are present even where Apollo's location
//      tagging is off. Names are resolved through Apollo before use; a name
//      that doesn't resolve is dropped, never guessed.
//
// Every kept row is enriched via organizations/enrich (FREE, domain-keyed —
// same call the US backfill used) for the real employee count, canonical
// name, industry and short description. The US list's known data debt came
// from name→domain guessing; this pipeline never writes a domain Apollo
// didn't return.
//
// Also builds the GLOBAL list (rest of world: headquartered outside the US
// and India) with --region global — same pipeline, the location filter flips
// to organization_not_locations and the seed comes from global-seed.json.
//
// Usage: node scripts/build-india-directory.mjs [--write] [--cap 2000] [--region in|global]

import fs from "node:fs";

const env = fs.readFileSync(new URL("../.env.local", import.meta.url), "utf8");
const g = (k) => {
  const m = env.match(new RegExp(`^${k}=(.*)$`, "m"));
  return m ? m[1].trim() : "";
};
const U = g("SUPABASE_URL"), SVC = g("SUPABASE_SERVICE_ROLE_KEY"), APOLLO = g("APOLLO_API_KEY");
if (!U || !SVC) throw new Error("Supabase env missing");
if (!APOLLO) throw new Error("APOLLO_API_KEY missing");
const H = { apikey: SVC, Authorization: `Bearer ${SVC}`, "Content-Type": "application/json" };
const WRITE = process.argv.includes("--write");
const capArg = process.argv.indexOf("--cap");
const CAP = capArg > -1 ? Number(process.argv[capArg + 1]) || 2000 : 2000;
const regionArg = process.argv.indexOf("--region");
const REGION = regionArg > -1 ? process.argv[regionArg + 1] : "in";
if (REGION !== "in" && REGION !== "global") throw new Error("--region must be 'in' or 'global'");
const SEED_FILE = REGION === "in" ? "./india-seed.json" : "./global-seed.json";
// in     → include-filter to India.
// global → rest of world: exclude the two markets that have their own lists.
const LOC_PARAMS =
  REGION === "in"
    ? { organization_locations: ["India"] }
    : { organization_not_locations: ["United States", "India"] };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// --- lib/companyKey.ts normCompany, replicated exactly ---
const COMPANY_SUFFIX =
  /\b(inc|incorporated|corp|corporation|co|company|llc|ltd|limited|gmbh|plc|sa|ag|nv|bv|pte|pvt|private|holdings)\b/g;
const normCompany = (s) =>
  s.toLowerCase().replace(/[.,]/g, " ").replace(COMPANY_SUFFIX, " ").replace(/[^a-z0-9]+/g, " ").trim();
const rootDomain = (d) => {
  const p = (d || "").toLowerCase().trim().replace(/^www\./, "").split(".").filter(Boolean);
  return p.length <= 2 ? p.join(".") : p.slice(-2).join(".");
};

const AH = { "x-api-key": APOLLO, "Content-Type": "application/json", Accept: "application/json", "Cache-Control": "no-cache" };
const APOLLO_BASE = "https://api.apollo.io/api/v1";

async function apolloSearch(params) {
  const qs = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (Array.isArray(v)) for (const x of v) qs.append(`${k}[]`, x);
    else qs.set(k, String(v));
  }
  const res = await fetch(`${APOLLO_BASE}/mixed_companies/search?${qs}`, { method: "POST", headers: AH });
  if (res.status === 429) { console.log("  rate limited — pausing 30s"); await sleep(30_000); return apolloSearch(params); }
  if (!res.ok) return null;
  return res.json();
}

async function apolloEnrich(domain) {
  const res = await fetch(`${APOLLO_BASE}/organizations/enrich?domain=${encodeURIComponent(domain)}`, { headers: AH });
  if (res.status === 429) { console.log("  rate limited — pausing 30s"); await sleep(30_000); return apolloEnrich(domain); }
  if (!res.ok) return null;
  return (await res.json())?.organization ?? null;
}

// Industry/keyword text -> app SegmentId. India-tuned: IT services map to
// "enterprise" (huge legacy/service codebases), product software to "saas".
function segmentOf(text) {
  const t = (text || "").toLowerCase();
  if (/e-?commerce|marketplace|online retail/.test(t)) return "marketplace";
  if (/fintech|bank|financial|insurance|payment|lending|nbfc|asset management|broker|exchange/.test(t)) return "fintech";
  if (/artificial intelligence|\bai\b|machine learning/.test(t)) return "ai";
  if (/developer|devops|api platform|open.?source/.test(t)) return "devtools";
  if (/computer software|saas|internet|information technology & services|software development/.test(t) && !/consult|outsourc|bpo/.test(t)) return "saas";
  if (/pharma|health|hospital|biotech|life science|diagnostic/.test(t)) return "health";
  if (/automotive|auto components|two.?wheeler|vehicle|mobility|tyre/.test(t)) return "auto";
  if (/retail|consumer goods|fmcg|food|beverage|apparel|jewell?ery|hospitality|hotel/.test(t)) return "retail";
  if (/telecom|media|entertainment|broadcast|publish|gaming|film/.test(t)) return "media";
  if (/logistics|supply chain|transport|airline|aviation|shipping|courier|railway/.test(t)) return "logistics";
  if (/defen[cs]e|aerospace/.test(t)) return "defense";
  if (/manufactur|industrial|steel|cement|chemical|mining|metal|energy|oil|gas|power|utilit|construction|infrastructure|engineering|textile|paper|glass/.test(t)) return "industrial";
  if (/outsourc|bpo|consult|it services|staffing/.test(t)) return "enterprise";
  return "enterprise";
}

// Modeled SWE share — same 35% tech-native / 3% traditional split the US
// pipeline uses (modeledSweFromOrg).
const TECH_RE = /software|information technology|internet|saas|fintech|computer|technology|e-?commerce|telecom/i;
const sweOf = (employees, industryText) => {
  if (!employees) return undefined;
  const share = TECH_RE.test(industryText || "") ? 0.35 : 0.03;
  return Math.max(10, Math.round(employees * share));
};

// Deterministic 0-95 fit strength from modeled SWE + a segment nudge, for the
// directory's default sort. Same spirit as the US list: engineering scale is
// most of the signal.
function strengthOf(swe, segment) {
  let s = swe === undefined ? 40
    : swe >= 5000 ? 88 : swe >= 2000 ? 82 : swe >= 1000 ? 76 : swe >= 500 ? 68
    : swe >= 250 ? 60 : swe >= 100 ? 52 : 42;
  if (["saas", "fintech", "devtools", "ai", "marketplace"].includes(segment)) s += 5;
  return Math.min(95, s);
}

const bandLabel = (n) =>
  n >= 100000 ? "100,000+ employees" : n >= 50000 ? "50,000+ employees" : n >= 20000 ? "20,000+ employees"
  : n >= 10000 ? "10,000+ employees" : n >= 5000 ? "5,000+ employees" : n >= 1000 ? "1,000+ employees" : "under 1,000";

// ---------------------------------------------------------------------------
// 1. Apollo India sweep, largest bands first.
// ---------------------------------------------------------------------------
const BANDS = ["100001,1000000", "50001,100000", "20001,50000", "10001,20000", "5001,10000", "2001,5000", "1001,2000", "501,1000"];
const candidates = new Map(); // rootDomain -> {name, domain, fromBand}
for (const band of BANDS) {
  if (candidates.size >= CAP + 700) break;
  let pages = 1;
  for (let page = 1; page <= Math.min(pages, 25); page++) {
    const body = await apolloSearch({
      ...LOC_PARAMS,
      "organization_num_employees_ranges": [band],
      page, per_page: 100,
    });
    if (!body) break;
    pages = Number(body.pagination?.total_pages) || 1;
    const orgs = [...(body.organizations ?? []), ...(body.accounts ?? [])];
    for (const o of orgs) {
      const dom = typeof o.primary_domain === "string" && o.primary_domain ? rootDomain(o.primary_domain) : null;
      const nm = typeof o.name === "string" ? o.name.trim() : "";
      if (!dom || !nm) continue; // no domain = no exact key; the curated pass may still catch it
      if (!candidates.has(dom)) candidates.set(dom, { name: nm, domain: dom, fromBand: band });
    }
    await sleep(350);
    if (orgs.length < 100) break;
  }
  console.log(`band ${band}: ${candidates.size} cumulative candidates`);
}

// ---------------------------------------------------------------------------
// 2. Curated seed — resolve names Apollo's sweep missed.
// ---------------------------------------------------------------------------
let seed = [];
try {
  seed = JSON.parse(fs.readFileSync(new URL(SEED_FILE, import.meta.url), "utf8")).companies ?? [];
} catch {
  console.log(`no scripts/${SEED_FILE.slice(2)} — sweep only`);
}
const haveName = new Set([...candidates.values()].map((c) => normCompany(c.name)));
let resolved = 0, unresolvable = 0;
for (const s of seed) {
  if (!s.name || haveName.has(normCompany(s.name))) continue;
  if (s.domain && candidates.has(rootDomain(s.domain))) continue;
  // Domain from the agents is a HINT — verify through enrich before trusting.
  let dom = s.domain ? rootDomain(s.domain) : null;
  if (!dom) {
    const body = await apolloSearch({ q_organization_name: s.name, ...LOC_PARAMS, page: 1, per_page: 5 });
    const orgs = [...(body?.organizations ?? []), ...(body?.accounts ?? [])];
    const target = normCompany(s.name);
    const hit = orgs.find((o) => normCompany(String(o.name ?? "")) === target) ?? orgs[0];
    dom = hit && typeof hit.primary_domain === "string" && hit.primary_domain ? rootDomain(hit.primary_domain) : null;
    await sleep(350);
  }
  if (!dom) { unresolvable += 1; continue; }
  if (!candidates.has(dom)) {
    candidates.set(dom, { name: s.name, domain: dom, fromSeed: true });
    haveName.add(normCompany(s.name));
    resolved += 1;
  }
}
console.log(`curated seed: +${resolved} new, ${unresolvable} names Apollo could not resolve (dropped, not guessed)`);

// ---------------------------------------------------------------------------
// 3. Enrich every candidate (free) for real employees + industry + brief.
// Eight workers — sequential at ~750ms/call would run past 30 minutes.
// ---------------------------------------------------------------------------
const rows = [];
let dropped = 0;
const queue = [...candidates.values()];
let qi = 0, done = 0;
async function enrichWorker() {
  for (;;) {
    const c = queue[qi++];
    if (!c) return;
    done += 1;
    if (done % 250 === 0) console.log(`  enriched ${done}/${queue.length}…`);
    const org = await apolloEnrich(c.domain);
    await sleep(120);
    processOrg(c, org);
  }
}
// Not companies: India's biggest "employers" in Apollo include state
// departments, police forces, universities and schools. A prospecting
// directory wants none of them (first run surfaced "Basic Education
// Department, Uttar Pradesh" at #2 with 624K teachers).
const NOT_A_COMPANY =
  /\b(university|universit|college|school|institute of|polytechnic|academy of|police|army|navy|air force|ministry|government|govt\.?|municipal|panchayat|zilla|district court|state road transport|forest department|education department)\b/i;
const GOV_DOMAIN = /\.(gov|nic|ac)\.in$|\.edu$/i;

function processOrg(c, org) {
  if (!org) { dropped += 1; return; }
  const checkName = `${c.name} ${typeof org.name === "string" ? org.name : ""}`;
  const checkDomain = typeof org.primary_domain === "string" ? org.primary_domain : c.domain;
  // Underscores never appear in real company names — they mark junk Apollo
  // records ("TCS_India", an ultimatix.net dup of TCS that landed at #2).
  if (NOT_A_COMPANY.test(checkName) || GOV_DOMAIN.test(checkDomain) || /_/.test(checkName)) { dropped += 1; return; }
  const employees = typeof org.estimated_num_employees === "number" && Number.isFinite(org.estimated_num_employees)
    ? org.estimated_num_employees : undefined;
  // Under 500 employees can't be a "largest companies in India" row — for a
  // sweep candidate it means a mis-tagged or shell org; drop.
  if (!employees || employees < 500) { dropped += 1; return; }
  const country = typeof org.country === "string" ? org.country : "";
  const wrongCountry =
    REGION === "in"
      ? country && !/india/i.test(country)
      : country && /(united states|^usa?$|india)/i.test(country);
  if (wrongCountry) { dropped += 1; return; }
  const name = (typeof org.name === "string" && org.name.trim()) || c.name;
  const industryText = [org.industry, ...(Array.isArray(org.keywords) ? org.keywords.slice(0, 12) : [])].filter(Boolean).join(" ");
  const segment = segmentOf(industryText);
  const swe = sweOf(employees, industryText);
  const briefRaw = typeof org.short_description === "string" ? org.short_description.trim() : "";
  const brief = briefRaw.length > 420 ? briefRaw.slice(0, 420).replace(/\s+\S*$/, "") + "…" : briefRaw;
  rows.push({
    company_key: normCompany(name),
    company: name,
    domain: typeof org.primary_domain === "string" && org.primary_domain ? org.primary_domain : c.domain,
    region: "in",
    segment,
    swe_estimate: swe ?? null,
    short_brief: brief || null,
    employee_band: bandLabel(employees),
    estimated_employees: employees,
    website_url: typeof org.website_url === "string" ? org.website_url : null,
    linkedin_url: typeof org.linkedin_url === "string" ? org.linkedin_url : null,
    strength: strengthOf(swe, segment),
    source: "india-directory",
    last_seen_at: new Date().toISOString(),
  });
}
await Promise.all(Array.from({ length: 8 }, () => enrichWorker()));
console.log(`${rows.length} enriched rows (${dropped} dropped: no data / <500 employees / not India)`);

// ---------------------------------------------------------------------------
// 4. Dedupe, protect US rows, rank, cap, upsert.
// ---------------------------------------------------------------------------
const usKeys = new Set(
  (await (await fetch(`${U}/rest/v1/bito_directory?select=company_key&region=eq.us&limit=5000`, { headers: H })).json())
    .map((r) => r.company_key),
);
const byKey = new Map();
for (const r of rows) {
  if (!r.company_key) continue;
  if (usKeys.has(r.company_key)) { console.log(`  key collides with a US row, skipped: ${r.company}`); continue; }
  const prev = byKey.get(r.company_key);
  if (!prev || (r.estimated_employees ?? 0) > (prev.estimated_employees ?? 0)) byKey.set(r.company_key, r);
}
const final = [...byKey.values()].sort((a, b) => (b.estimated_employees ?? 0) - (a.estimated_employees ?? 0)).slice(0, CAP);
console.log(`${final.length} final rows${WRITE ? "" : " (dry run — pass --write to apply)"}`);
const mix = {};
for (const r of final) mix[r.segment] = (mix[r.segment] ?? 0) + 1;
console.log("segment mix:", JSON.stringify(mix));
console.log("top 15:", final.slice(0, 15).map((r) => `${r.company} (~${r.estimated_employees.toLocaleString()})`).join(", "));

if (WRITE) {
  for (let o = 0; o < final.length; o += 500) {
    const res = await fetch(`${U}/rest/v1/bito_directory?on_conflict=company_key`, {
      method: "POST",
      headers: { ...H, Prefer: "resolution=merge-duplicates,return=minimal" },
      body: JSON.stringify(final.slice(o, o + 500)),
    });
    if (!res.ok) throw new Error(`upsert ${res.status}: ${await res.text()}`);
  }
  const count = await fetch(`${U}/rest/v1/bito_directory?select=company_key&region=eq.in`, {
    method: "HEAD", headers: { ...H, Prefer: "count=exact" },
  });
  console.log(`Upserted. bito_directory region='in' now has ${count.headers.get("content-range")?.split("/")[1]} rows.`);
}
